-- Lesson 0 of 7 | Create Sample Tables
-- Indexes only matter on big tables, so we make a register of 20000 pupils.
-- The rows are generated by a recursive WITH query, which counts from 1 to 20000.
-- The data follows fixed rules, so every run produces exactly the same rows.

CREATE TABLE pupils (
    pupil_id  INTEGER PRIMARY KEY,
    name      TEXT NOT NULL,
    city      TEXT NOT NULL,
    marks     INTEGER NOT NULL,
    roll_code TEXT NOT NULL
);

WITH RECURSIVE numbers(n) AS (
    SELECT 1
    UNION ALL
    SELECT n + 1 FROM numbers WHERE n < 20000
)
INSERT INTO pupils (pupil_id, name, city, marks, roll_code)
SELECT n,
       'Pupil ' || n,
       CASE n % 5
           WHEN 0 THEN 'Chennai'
           WHEN 1 THEN 'Pune'
           WHEN 2 THEN 'Delhi'
           WHEN 3 THEN 'Mumbai'
           ELSE 'Kochi'
       END,
       (n * 37) % 101,
       'R' || printf('%05d', n)
FROM numbers;

SELECT COUNT(*) AS pupils_in_table
FROM pupils;

SELECT pupil_id, name, city, marks, roll_code
FROM pupils
ORDER BY pupil_id
LIMIT 3;

SELECT city, COUNT(*) AS pupils
FROM pupils
GROUP BY city
ORDER BY city;